/*
 * Dualkit Starter components. Load after @dualkit/starter/tokens.css.
 * Every value comes from a --dk- token; the few raw numbers are geometry from the Figma frames
 * (1px hairlines, the 2px focus gap and ring, 44x52 code boxes, 32px close button).
 * Logical properties throughout, so dir="rtl" mirrors everything with no extra rules,
 * except the few things that move: directional icons and the sheet's slide, both on :dir(), which follows
 * the nearest dir attribute (an [dir="rtl"] ancestor selector would also match an LTR block nested inside).
 */

/* Type roles. :lang(ar) swaps the family, size, leading and tracking in tokens.css. */
.dk-label { font-family: var(--dk-type-label-family); font-size: var(--dk-type-label-size); font-weight: var(--dk-type-label-weight); line-height: var(--dk-type-label-leading); letter-spacing: var(--dk-type-label-tracking); }
