.dk-caption { margin: 0; font-family: var(--dk-type-caption-family); font-size: var(--dk-type-caption-size); font-weight: var(--dk-type-caption-weight); line-height: var(--dk-type-caption-leading); letter-spacing: var(--dk-type-caption-tracking); }
.dk-title { margin: 0; font-family: var(--dk-type-title-family); font-size: var(--dk-type-title-size); font-weight: var(--dk-type-title-weight); line-height: var(--dk-type-title-leading); letter-spacing: var(--dk-type-title-tracking); }
.dk-mono { font-family: var(--dk-font-family-mono); font-size: var(--dk-font-size-14); font-weight: var(--dk-font-weight-regular); line-height: var(--dk-font-line-height-140); }
.dk-secondary { color: var(--dk-color-text-secondary); }
.dk-tertiary { color: var(--dk-color-text-tertiary); }
.dk-danger { color: var(--dk-color-state-danger); }

.dk-icon { flex: none; display: block; }
.dk-icon--directional:dir(rtl) { transform: scaleX(-1); }

/* Button: a pill. The focus ring is offset: a ground-coloured gap, then the ink ring, zero blur. */
.dk-button {
  display: inline-flex; align-items: center; gap: var(--dk-space-inline-sm);
  padding-block: var(--dk-space-inline-md); padding-inline: var(--dk-space-stack-lg);
  border: 0; border-radius: var(--dk-radius-control); cursor: pointer;
  font-family: var(--dk-type-label-family); font-size: var(--dk-type-label-size); font-weight: var(--dk-type-label-weight); line-height: var(--dk-type-label-leading); letter-spacing: var(--dk-type-label-tracking);
  transition: background-color var(--dk-motion-duration-fast) var(--dk-motion-easing-standard), scale var(--dk-motion-duration-base) var(--dk-motion-easing-out);
